 * @param {number[][]} edges
 * @param {string} labels
 * @param {number} k
 * @return {number}
 */
var shortestPath = function(n, edges, labels, k) {
    const graph = Array.from({ length: n }, (_, i) => ({ char: labels[i], children: new Map() }));

    for (const [u, v, w] of edges) {
        graph[u].children.set(v, w);
    }

    let stack = [[0, '', 0, 0]];
    const dp = Array.from({ length: n }, () => ({}));
    let res = Infinity;

    while (stack.length > 0) {
        const next = [];

        for (let [node, char, count, total] of stack) {
            const dpKey = char + ':' + count;
            if (dp[node][dpKey] !== undefined && dp[node][dpKey] <= total) continue;
            dp[node][dpKey] = total;

            if (char === graph[node].char) {
                count++;

                if (count > k) continue;
            } else {
                char = graph[node].char;
                count = 1;
            }

            if (node === n - 1) {
                res = Math.min(res, total);
                continue;
            }

            for (const [con, weight] of graph[node].children) {
                next.push([con, char, count, total + weight]);
            }
        }

        stack = next;
    }

    return res === Infinity ? -1 : res;
};

