/**
 * @param {number} n
 * @param {number[][]} edges
 * @param {string} labels
 * @param {number} k
 * @return {number}
 */
var shortestPath = function(n, edges, labels, k) {
    const graph = Array.from({ length: n }, () => new Map());

    for (const [u, v, w] of edges) {
        graph[u].set(v, Math.min(graph[u].get(v) ?? Infinity, w));
    }

    const heap = new MinPriorityQueue(x => x[2]);
    heap.enqueue([0, 1, 0]);

    const dp = Array.from({ length: n }, () => Array(k + 1).fill(Infinity));
    dp[0][1] = 0;

    while (!heap.isEmpty()) {
        const [node, count, total] = heap.dequeue();

        if (total > dp[node][count]) continue;

        if (node === n - 1) return total;

        for (const [next, weight] of graph[node]) {
            const nextCount = labels[node] === labels[next] ? count + 1 : 1;

            if (nextCount > k) continue;

            const nextTotal = total + weight;

            if (nextTotal >= dp[next][nextCount]) continue;

            dp[next][nextCount] = nextTotal;
            heap.enqueue([next, nextCount, nextTotal]);
        }
    }

    return -1;
};
